from collections import Counter

def can_we_give(freq, packets, n):
    fullfilled = 0
    for food_packets in freq.keys():
        fullfilled += freq[food_packets] // packets
    if fullfilled >= n:
        return True
    else:
        return False


def main():
    # Taking input
    n, m = (int(num) for num in input().split())
    A = [int(num) for num in input().split()]
    if m < n:    # Base Case
        print(0)
    else:
        freq = Counter(A)    # Frequency of each and every food packets
        l, r = 1, max(freq.values())
        while l < r:
            mid = (l+r+1) // 2
            if can_we_give(freq, mid, n):
                l = mid
            else:
                r = mid - 1

        print(l)

if __name__ == '__main__':
    main()

from collections import Counter
n,k = map(int,input().split(" "))
l = [int(c) for c in input().split(" ")]
d = list(Counter(l).values())
if k<n:
    print(0)
else:
    m = k//n
    p=0
    for i in range(1,m+1):
        s = 0
        for j in d:
            s += j//i
        if s>=n:
            p=i
        else:
            break
    print(p)

def Ludi(t, d):
    sum = 0
    if t != 0:
        for i in d:
            sum += d[i] // t
        return sum
    else:
        return 0

n, m = map(int, input().split())
a = list(map(int, input().split()))
vis = [0 for i in range(105)]
for i in range(m):
    vis[a[i]] += 1
ans = 0
for i in range(1, m + 1):
    cnt = 0
    for j in range(1, 101):
        cnt += vis[j] // i
    if cnt >= n:
        ans = max(ans, i)
print(ans)
